-- 신조어 16개 승격 + 짝 단어 2개 신규 등록 (2026-09-04 아침 검수 2차, 운영자 승인).
--
-- 승격(ids 227-238, 241-244): 대박, 소름, 화이팅, 덕질, 직캠, 포카, 예판, 팬덤, 떡밥,
--   떡상, 혼밥, 찐친, 핵이득, 본캐, 케바케, 월급 루팡.
--   slang_candidates의 draft_payload를 그대로 옮기며, id는 created_at 순으로 매긴다.
-- 신규(ids 246-247): 떡락, 먹금 — 운영자가 각각 떡상·떡밥의 짝으로 함께 등록하라고 지시한 단어.
--   후보 테이블에 없어 이 파일에서 새로 작성했다.
-- 보류: 미쳤다, 커터칼퇴, 얼렁뚱땡이, 뉴아르.
--
-- 알파벳·한글 병기어(JMT/제이엠티/존맛탱, TMI/티엠아이) 처리:
--   표기마다 표제어를 나누면 같은 단어가 검색 결과에 두 번 나온다. 그래서 표제어는 하나만 두고
--   나머지 표기는 words.aliases(migration add_words_aliases)에 넣어 검색에만 태운다.
--   화면에는 노출하지 않으며, 어느 표기로 검색해도 항목 하나로 모인다는 사실은
--   usage/usage_i18n에 설명으로 적는다.
--   승인된 후보 중 '티엠아이'와 'JMT'는 사전에 이미 TMI(21)·존맛탱(102)으로 있어서 새 표제어를
--   만들지 않고 그 두 행에 별칭과 설명만 붙였다(아래 update). 같은 이유로 '개이득'도 이미
--   id 11로 있어 짝 단어 신규 등록에서 제외했다. gating(존맛탱은 slang 카테고리 = 성인 게이트)과
--   기존 id를 그대로 두는 쪽이 안전해서 새 행이 아니라 기존 행을 살렸다.
--
-- NOTE: filename timestamp differs from the production migration version
-- (MCP apply time becomes the version) — repo-wide convention, see CLAUDE.md.

begin;

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "227", "word": "대박", "likes": 0, "saves": 0, "usage": "좋은 소식이나 놀라운 상황 모두에 감탄사로 널리 쓴다.", "origin": "도박 용어 '대박(大博)'에서 온 말로, 2000년대 초부터 감탄사로 널리 쓰이기 시작했다.", "category": "exclamation", "meanings": [{"type": "감탄사", "examples": [{"de": "Der Sale heute ist der Wahnsinn!", "es": "¡La oferta de hoy es increíble!", "ja": "今日のセール、やばい！", "vi": "Sale hôm nay đỉnh quá!", "eng": "Today's sale is amazing!", "kor": "오늘 세일 대박이다!"}], "definition": "도박에서 판돈을 크게 딴 것을 뜻하던 '대박(大博)'에서 온 감탄사로, 지금은 좋은 의미든 놀라운 의미든 무언가 엄청날 때 널리 쓴다.", "definition_i18n": {"de": "Von 'daebak' (großer Gewinn beim Glücksspiel); heute ein vielseitiger Ausruf für alles Erstaunliche, ob gute Nachricht oder Schock.", "en": "From 'daebak' (big win in gambling); now a versatile exclamation for anything amazing, whether good news or a shock.", "es": "De 'daebak' (gran ganancia en apuestas); ahora una exclamación versátil para algo asombroso, sea buena noticia o una sorpresa.", "ja": "賭博で大金を得たことを意味した「대박」由来の感嘆詞。今では良い意味でも驚きの意味でも何かすごい時に幅広く使う。", "vi": "Từ 'daebak' (thắng lớn trong cờ bạc); nay là thán từ linh hoạt cho điều gì đó tuyệt vời, dù là tin vui hay cú sốc."}}], "created_at": "2026-09-04T08:30:00+00:00", "short_desc": "엄청나거나 놀랍다는 뜻의 감탄사", "usage_i18n": {"de": "Wird häufig als Ausruf sowohl für gute Nachrichten als auch überraschende Situationen verwendet.", "en": "Widely used as an exclamation for both good news and surprising situations.", "es": "Ampliamente usado como exclamación tanto para buenas noticias como situaciones sorprendentes.", "ja": "良い知らせにも驚きの状況にも感嘆詞として広く使う。", "vi": "Dùng rộng rãi làm thán từ cho cả tin vui lẫn tình huống bất ngờ."}, "origin_i18n": {"de": "Vom Glücksspielbegriff 'Daebak'; wurde seit den frühen 2000ern zu einem weit verbreiteten Ausruf.", "en": "From the gambling term 'daebak'; became a widespread exclamation from the early 2000s.", "es": "Del término de apuestas 'daebak'; se convirtió en una exclamación generalizada desde principios de los 2000.", "ja": "賭博用語「대박」由来で、2000年代初頭から感嘆詞として広く使われ始めた。", "vi": "Từ thuật ngữ cờ bạc 'daebak'; trở thành thán từ phổ biến từ đầu những năm 2000."}, "romanization": "Dae-bak", "translations": [{"lang": "🇺🇸 EN", "text": "Jackpot / amazing"}, {"lang": "🇯🇵 JA", "text": "やばい（すごい）"}, {"lang": "🇨🇳 ZH", "text": "太厉害了"}, {"lang": "🇻🇳 VI", "text": "Đỉnh quá"}, {"lang": "🇪🇸 ES", "text": "Increíble"}, {"lang": "🇩🇪 DE", "text": "Der Wahnsinn"}], "pronunciation": "[대박]", "related_words": ["미쳤다", "오지다"], "short_desc_i18n": {"de": "Ein Ausruf für etwas Erstaunliches oder Überraschendes", "en": "An exclamation for something amazing or surprising", "es": "Una exclamación para algo asombroso o sorprendente", "ja": "すごい・驚いたという感嘆詞", "vi": "Thán từ chỉ điều tuyệt vời hoặc bất ngờ"}}$json$::jsonb);

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "228", "word": "소름", "likes": 0, "saves": 0, "usage": "음악, 연기, 우연의 일치 등 소름 끼칠 정도로 인상적인 순간에 쓴다.", "origin": "'소름 돋다'(피부 반응)라는 일반 표현이 감탄사로 축약돼 인터넷·방송에서 널리 쓰이게 됐다.", "category": "exclamation", "meanings": [{"type": "감탄사", "examples": [{"de": "Diese hohe Note gab mir eine Gänsehaut.", "es": "Esa nota alta me dio escalofríos.", "ja": "あの高音、鳥肌立った。", "vi": "Nốt cao đó nổi da gà luôn.", "eng": "That high note gave me chills.", "kor": "저 고음 소름이다."}], "definition": "'소름이 돋는다'(피부에 소름이 일어나다)를 줄여 감탄사처럼 쓰는 말로, 놀랍거나 감동적이거나 오싹할 정도로 대단할 때 쓴다.", "definition_i18n": {"de": "Kurz für 'sorm-i dotneunda' (Gänsehaut auf der Haut), als Ausruf für etwas Schockierendes, Bewegendes oder unheimlich Beeindruckendes verwendet.", "en": "Short for 'sorm-i dotneunda' (goosebumps rising on the skin), used as an exclamation for something shocking, moving, or eerily impressive.", "es": "Abreviatura de 'sorm-i dotneunda' (piel de gallina), usada como exclamación para algo impactante, conmovedor o inquietantemente impresionante.", "ja": "「소름이 돋는다」（鳥肌が立つ）を略して感嘆詞的に使う言葉で、驚いたり感動したり、ぞっとするほどすごい時に使う。", "vi": "Viết tắt của 'sorm-i dotneunda' (nổi da gà), dùng làm thán từ cho điều gì đó gây sốc, cảm động, hoặc ấn tượng đến rùng mình."}}], "created_at": "2026-09-04T08:30:00+00:00", "short_desc": "'소름 돋는다'로 쓰는 감탄 표현", "usage_i18n": {"de": "Wird für Momente verwendet, die beeindruckend genug sind, um Gänsehaut zu verursachen — Musik, Schauspiel, ein auffälliger Zufall usw.", "en": "Used for moments impressive enough to raise goosebumps — music, acting, a striking coincidence, etc.", "es": "Se usa para momentos lo bastante impresionantes como para dar piel de gallina — música, actuación, una coincidencia sorprendente, etc.", "ja": "音楽、演技、偶然の一致など鳥肌が立つほど印象的な瞬間に使う。", "vi": "Dùng cho khoảnh khắc ấn tượng đến mức nổi da gà — âm nhạc, diễn xuất, sự trùng hợp bất ngờ, v.v."}, "origin_i18n": {"de": "Die allgemeine Phrase 'sorm dotda' (eine Hautreaktion) wurde zu einem Ausruf verkürzt, weit verbreitet online und in Sendungen.", "en": "The general phrase 'sorm dotda' (a skin reaction) shortened into an exclamation, widely used online and on broadcasts.", "es": "La frase general 'sorm dotda' (una reacción de la piel) se abrevió a una exclamación, ampliamente usada en línea y en emisiones.", "ja": "「소름 돋다」（皮膚反応）という一般表現が感嘆詞に略され、ネットや放送で広く使われるようになった。", "vi": "Cụm từ chung 'sorm dotda' (phản ứng của da) được rút gọn thành thán từ, dùng rộng rãi trên mạng, truyền hình."}, "romanization": "So-reum", "translations": [{"lang": "🇺🇸 EN", "text": "Chills / goosebumps"}, {"lang": "🇯🇵 JA", "text": "鳥肌"}, {"lang": "🇨🇳 ZH", "text": "起鸡皮疙瘩"}, {"lang": "🇻🇳 VI", "text": "Nổi da gà"}, {"lang": "🇪🇸 ES", "text": "Escalofríos"}, {"lang": "🇩🇪 DE", "text": "Gänsehaut"}], "pronunciation": "[소름]", "related_words": ["ㄷㄷ", "미쳤다"], "short_desc_i18n": {"de": "'Gänsehaut!' — verwendet als 'Sorm dotneunda'", "en": "'Chills!' — used as 'sorm dotneunda' (goosebumps)", "es": "'¡Escalofríos!' — usado como 'piel de gallina'", "ja": "「鳥肌が立つ」という感嘆表現", "vi": "'Nổi da gà!' — cách nói khi rùng mình"}}$json$::jsonb);

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "229", "word": "화이팅", "likes": 0, "saves": 0, "usage": "시험·면접·경기 등을 앞두고 응원하거나 자기 자신을 다독일 때 널리 쓴다.", "origin": "영어 'fighting'을 한국식으로 받아들인 콩글리시 표현으로, 스포츠 응원에서 시작돼 일상 격려 표현으로 확장됐다.", "category": "exclamation", "meanings": [{"type": "응원 감탄사", "examples": [{"de": "Viel Erfolg bei der Prüfung, fighting!", "es": "¡Suerte en el examen, fighting!", "ja": "試験ファイト！", "vi": "Thi cử cố lên nhé, fighting!", "eng": "Good luck on the exam, fighting!", "kor": "시험 화이팅!"}], "definition": "영어 'fighting'에서 왔지만 실제 싸움과는 무관한 콩글리시 응원 표현. '할 수 있다, 힘내자, 가자'에 가까운 뜻으로 시험·경기·힘든 상황 전반에서 쓴다.", "definition_i18n": {"de": "Vom englischen 'Fighting', aber Konglish und ohne Bezug zu echtem Kampf; bedeutet etwa 'du schaffst das, gib alles.' Wird breit vor Prüfungen, Spielen oder schwierigen Situationen verwendet.", "en": "From English 'fighting,' but Konglish and unrelated to actual fighting; means something like 'you can do it, go for it.' Used broadly before exams, games, or tough situations.", "es": "Del inglés 'fighting,' pero es konglish y no tiene relación con pelear; significa algo como 'tú puedes, dale.' Se usa ampliamente antes de exámenes, partidos o situaciones difíciles.", "ja": "英語「fighting」由来だが実際の争いとは無関係なコングリッシュの応援表現。「できる、頑張ろう、行こう」に近い意味で試験・試合・大変な状況全般で使う。", "vi": "Từ 'fighting' tiếng Anh, nhưng là tiếng Anh kiểu Hàn (Konglish) không liên quan đến đánh nhau; nghĩa gần giống 'bạn làm được, cố lên.' Dùng rộng rãi trước kỳ thi, trận đấu, tình huống khó khăn."}}], "created_at": "2026-09-04T08:30:00+00:00", "short_desc": "'할 수 있어, 힘내자'라는 응원 표현", "usage_i18n": {"de": "Wird häufig verwendet, um jemanden (oder sich selbst) vor einer Prüfung, einem Interview, Spiel usw. anzufeuern.", "en": "Widely used to cheer someone (or oneself) on before an exam, interview, game, etc.", "es": "Ampliamente usado para animar a alguien (o a uno mismo) antes de un examen, entrevista, partido, etc.", "ja": "試験・面接・試合などを控えた相手や自分自身を応援する時に広く使う。", "vi": "Dùng rộng rãi để cổ vũ ai đó (hoặc bản thân) trước kỳ thi, phỏng vấn, trận đấu, v.v."}, "origin_i18n": {"de": "Eine Konglish-Anpassung des englischen 'Fighting', die bei Sport-Anfeuerungen begann und sich zu alltäglicher Ermutigung ausweitete.", "en": "A Konglish adaptation of the English 'fighting,' starting in sports cheers and expanding into everyday encouragement.", "es": "Una adaptación konglish del inglés 'fighting,' que comenzó en las porras deportivas y se expandió al ánimo cotidiano.", "ja": "英語「fighting」を韓国式に取り入れたコングリッシュ表現で、スポーツ応援から始まり日常の激励表現に広がった。", "vi": "Cách chuyển thể Konglish từ 'fighting' tiếng Anh, bắt đầu từ cổ vũ thể thao và mở rộng thành lời động viên đời thường."}, "romanization": "Hwa-i-ting", "translations": [{"lang": "🇺🇸 EN", "text": "Fighting! (you got this)"}, {"lang": "🇯🇵 JA", "text": "ファイト！"}, {"lang": "🇨🇳 ZH", "text": "加油！"}, {"lang": "🇻🇳 VI", "text": "Fighting! (cố lên)"}, {"lang": "🇪🇸 ES", "text": "¡Fighting! (tú puedes)"}, {"lang": "🇩🇪 DE", "text": "Fighting! (du schaffst das)"}], "pronunciation": "[화이팅]", "related_words": ["중꺽마"], "short_desc_i18n": {"de": "'Fighting!' — ein Zuruf, der 'du schaffst das' bedeutet", "en": "'Fighting!' — a cheer meaning 'you got this'", "es": "'¡Fighting!' — un ánimo que significa 'tú puedes'", "ja": "「頑張れ、できる」という応援表現", "vi": "'Fighting!' — lời cổ vũ nghĩa 'bạn làm được'"}}$json$::jsonb);

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "230", "word": "덕질", "likes": 0, "saves": 0, "usage": "좋아하는 연예인·캐릭터·취미에 시간과 애정을 쏟는 활동 전반을 가리킬 때 쓴다.", "origin": "일본어 '오타쿠'에서 온 '덕후'가 2005년 무렵 디시인사이드 애니메이션 갤러리에서 '오덕후'로 처음 쓰였고, 이후 '덕질'로 파생됐다.", "category": "kpop", "meanings": [{"type": "팬덤 용어", "examples": [{"de": "Ich bin gerade voll in diesen Schauspieler vertieft.", "es": "Últimamente estoy metido de lleno con este actor.", "ja": "最近この俳優を덕질してる。", "vi": "Dạo này đang mê mẩn diễn viên này lắm.", "eng": "I'm deep into stanning this actor lately.", "kor": "요즘 이 배우 덕질 중이야."}], "definition": "일본어 '오타쿠'를 한자식으로 바꾼 '덕후'에 '질'(행위)을 붙인 말로, 아이돌·애니메이션 등 좋아하는 대상에 깊이 몰두하는 팬 활동 전반을 이른다.", "definition_i18n": {"de": "Kombiniert 'deokhu' (eine sinokoreanische Anpassung des japanischen Otaku) mit 'jil' (ein Aktivitätssuffix); bezieht sich allgemein darauf, sich intensiv als Fan von Idolen, Anime usw. zu vertiefen.", "en": "Combines 'deokhu' (a Sino-Korean adaptation of Japanese otaku) with 'jil' (an activity suffix); refers broadly to deeply immersing oneself as a fan of idols, anime, etc.", "es": "Combina 'deokhu' (una adaptación sino-coreana del japonés otaku) con 'jil' (sufijo de actividad); se refiere ampliamente a sumergirse profundamente como fan de ídolos, anime, etc.", "ja": "日本語「オタク」を漢字語風に変えた「덕후」に「질」（行為）を付けた語で、アイドル・アニメなど好きな対象に深く没頭するファン活動全般を指す。", "vi": "Ghép 'deokhu' (biến thể Hán-Hàn của otaku Nhật) với 'jil' (hậu tố chỉ hành động); chỉ chung việc đắm chìm sâu làm fan của thần tượng, anime, v.v."}}], "created_at": "2026-09-04T08:30:00+00:00", "short_desc": "한 분야나 대상에 깊이 몰두하는 팬 활동", "usage_i18n": {"de": "Wird breit verwendet, um sich auf das Widmen von Zeit und Leidenschaft für einen Lieblingsstar, eine Figur oder ein Hobby zu beziehen.", "en": "Used to refer broadly to devoting time and passion to a favorite celebrity, character, or hobby.", "es": "Se usa ampliamente para referirse a dedicar tiempo y pasión a un famoso, personaje o afición favorita.", "ja": "好きな芸能人・キャラクター・趣味に時間と愛情を注ぐ活動全般を指す時に使う。", "vi": "Dùng chung để chỉ việc dành thời gian, tâm huyết cho người nổi tiếng, nhân vật, sở thích yêu thích."}, "origin_i18n": {"de": "'Deokhu' (vom japanischen Otaku) wurde erstmals um 2005 als 'o-deokhu' in einem Anime-Forum von DC Inside verwendet, woraus später 'deokjil' entstand.", "en": "'Deokhu' (from Japanese otaku) was first used as 'o-deokhu' around 2005 on a DC Inside anime forum, later giving rise to 'deokjil.'", "es": "'Deokhu' (del japonés otaku) se usó primero como 'o-deokhu' hacia 2005 en un foro de anime de DC Inside, dando origen luego a 'deokjil.'", "ja": "日本語「オタク」由来の「덕후」が2005年頃DCinsideアニメギャラリーで「오덕후」として初めて使われ、後に「덕질」が派生した。", "vi": "'Deokhu' (từ otaku Nhật) lần đầu dùng thành 'o-deokhu' khoảng năm 2005 trên diễn đàn anime DC Inside, sau đó sinh ra 'deokjil.'"}, "romanization": "Deok-jil", "translations": [{"lang": "🇺🇸 EN", "text": "Fan obsession / stanning"}, {"lang": "🇯🇵 JA", "text": "推し活"}, {"lang": "🇨🇳 ZH", "text": "追星/追坑"}, {"lang": "🇻🇳 VI", "text": "Mê mẩn (fan)"}, {"lang": "🇪🇸 ES", "text": "Ser fan a fondo"}, {"lang": "🇩🇪 DE", "text": "Fan-Obsession"}], "pronunciation": "[덕찔]", "related_words": ["입덕", "탈덕"], "short_desc_i18n": {"de": "Sich intensiv in ein Fandom oder Hobby vertiefen", "en": "Deeply immersing oneself in a fandom or hobby", "es": "Sumergirse profundamente en un fandom o afición", "ja": "ある分野や対象に深く没頭するファン活動", "vi": "Đắm chìm sâu vào fandom hoặc sở thích"}}$json$::jsonb);

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "231", "word": "직캠", "likes": 0, "saves": 0, "usage": "유튜브·SNS에 올라온 팬 촬영 아이돌 영상을 가리킬 때 쓴다.", "origin": "'직접 찍은 사진'을 뜻하던 '직찍'에서 파생돼 동영상 버전인 '직캠'이 됐다. 네이버 검색 기록상 2004년 무렵부터 쓰였다.", "category": "kpop", "meanings": [{"type": "팬덤 용어", "examples": [{"de": "Dieser Fancam hat wahnsinnig viele Aufrufe.", "es": "Ese fancam tiene un montón de vistas.", "ja": "あの직캠、再生数すごかった。", "vi": "Cái fancam đó view khủng luôn.", "eng": "That fancam's view count is insane.", "kor": "저 직캠 조회수 대박이더라."}], "definition": "'직접 촬영'의 줄임말. 방송사가 아닌 팬이 자기 카메라로 아이돌의 무대·행사를 찍어 올리는 영상을 이른다. 최근엔 멤버 한 명만 따라 찍는 '세로직캠'이 유행이다.", "definition_i18n": {"de": "Kurz für 'selbst gefilmt.' Bezieht sich auf Aufnahmen, die ein Fan (kein Sender) mit der eigenen Kamera von einer Idol-Bühne oder einem Event macht. Vertikale 'Solo-Fancams', die einem Mitglied folgen, sind derzeit im Trend.", "en": "Short for 'self-filmed.' Refers to footage a fan (not a broadcaster) shoots with their own camera of an idol's stage or event. Vertical 'solo fancams' following one member are currently trendy.", "es": "Abreviatura de 'filmado personalmente.' Se refiere a grabaciones que un fan (no una emisora) toma con su propia cámara del escenario o evento de un ídolo. Los 'fancams' verticales de un solo miembro son tendencia actual.", "ja": "「直接撮影」の略。放送局ではなくファンが自分のカメラでアイドルのステージやイベントを撮って投稿する映像を指す。最近はメンバー一人だけを追う「縦직캠」が流行。", "vi": "Viết tắt của 'tự quay.' Chỉ video fan (không phải đài truyền hình) tự quay bằng máy ảnh riêng cảnh sân khấu, sự kiện thần tượng. Gần đây thịnh hành 'fancam dọc' chỉ theo một thành viên."}}], "created_at": "2026-09-04T08:30:00+00:00", "short_desc": "팬이 아이돌을 직접 촬영해 올리는 영상", "usage_i18n": {"de": "Wird verwendet, um auf YouTube und sozialen Medien geposteten Fan-Videos von Idolen zu verweisen.", "en": "Used to refer to fan-shot idol videos posted on YouTube and social media.", "es": "Se usa para referirse a videos de ídolos grabados por fans publicados en YouTube y redes sociales.", "ja": "YouTubeやSNSに投稿されたファン撮影のアイドル映像を指す時に使う。", "vi": "Dùng để chỉ video thần tượng do fan quay đăng trên YouTube, mạng xã hội."}, "origin_i18n": {"de": "Abgeleitet von 'jikjjik' (persönlich aufgenommenes Foto), das sich zu Video als 'Jikkaem' erweiterte. Naver-Suchaufzeichnungen zeigen Verwendung seit etwa 2004.", "en": "Derived from 'jikjjik' (personally shot photo), which extended to video as 'jikkaem.' Naver search records show usage from around 2004.", "es": "Derivado de 'jikjjik' (foto tomada personalmente), que se extendió al video como 'jikkaem.' Los registros de búsqueda de Naver muestran uso desde alrededor de 2004.", "ja": "「直接撮った写真」を意味した「직찍」から派生し、動画版として「직캠」になった。Naver検索履歴上2004年頃から使われた。", "vi": "Bắt nguồn từ 'jikjjik' (ảnh tự chụp), mở rộng sang video thành 'jikkaem.' Lịch sử tìm kiếm Naver cho thấy dùng từ khoảng năm 2004."}, "romanization": "Jik-kaem", "translations": [{"lang": "🇺🇸 EN", "text": "Fancam"}, {"lang": "🇯🇵 JA", "text": "直撮り"}, {"lang": "🇨🇳 ZH", "text": "饭拍"}, {"lang": "🇻🇳 VI", "text": "Fancam"}, {"lang": "🇪🇸 ES", "text": "Fancam"}, {"lang": "🇩🇪 DE", "text": "Fancam"}], "pronunciation": "[직캠]", "related_words": ["홈마", "떡상"], "short_desc_i18n": {"de": "Ein 'Fancam' — Aufnahmen, die ein Fan persönlich von einem Idol macht", "en": "A 'fancam' — footage a fan personally shoots of an idol", "es": "Un 'fancam' — grabación que un fan hace personalmente de un ídolo", "ja": "ファンがアイドルを直接撮影した映像", "vi": "'Fancam' — video fan tự quay thần tượng"}}$json$::jsonb);

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "232", "word": "포카", "likes": 0, "saves": 0, "usage": "앨범 개봉·교환·수집 이야기를 할 때 널리 쓴다.", "origin": "영어 'photo card'를 줄인 팬덤 용어로, 앨범에 랜덤 카드를 동봉하는 K-pop 산업 관행과 함께 정착했다.", "category": "kpop", "meanings": [{"type": "팬덤 용어", "examples": [{"de": "Wer möchte Fotokarten tauschen?", "es": "¿Alguien para intercambiar fotocards?", "ja": "ポカ交換する人いる？", "vi": "Ai đổi photocard không?", "eng": "Anyone up for trading photocards?", "kor": "포카 교환하실 분?"}], "definition": "'포토카드'의 줄임말로, 아이돌 앨범이나 예판 특전으로 랜덤 동봉되는 멤버 개인 사진 카드를 이른다. 팬들 사이에서 원하는 멤버끼리 교환·거래하는 문화가 있다.", "definition_i18n": {"de": "Kurz für 'Fotokarte'; eine zufällig beigelegte Einzelfotokarte eines Mitglieds, die Idol-Alben oder Vorbestellungsboni beiliegt. Fans tauschen häufig Karten, um ihre Lieblingsmitglieder zu bekommen.", "en": "Short for 'photo card'; a randomly included individual member photo card bundled with idol albums or as a pre-order bonus. Fans commonly trade cards to get their favorite members.", "es": "Abreviatura de 'tarjeta fotográfica'; una tarjeta con la foto de un miembro incluida al azar con álbumes de ídolos o como bono de pre-orden. Los fans suelen intercambiar tarjetas para conseguir a sus miembros favoritos.", "ja": "「フォトカード」の略で、アイドルアルバムや予約特典としてランダム同封されるメンバー個人のフォトカードを指す。ファンの間で欲しいメンバー同士で交換・取引する文化がある。", "vi": "Viết tắt của 'thẻ ảnh'; thẻ ảnh cá nhân thành viên ngẫu nhiên kèm trong album thần tượng hoặc quà tặng đặt trước. Fan thường trao đổi thẻ để có thành viên yêu thích."}}], "created_at": "2026-09-04T08:30:00+00:00", "short_desc": "아이돌 앨범 속 수집용 사진 카드", "usage_i18n": {"de": "Wird häufig verwendet, wenn über das Auspacken, Tauschen oder Sammeln von Alben gesprochen wird.", "en": "Widely used when talking about unboxing, trading, or collecting albums.", "es": "Ampliamente usado al hablar de desempacar, intercambiar o coleccionar álbumes.", "ja": "アルバム開封・交換・収集の話をする時に広く使う。", "vi": "Dùng rộng rãi khi nói về mở hộp, trao đổi, sưu tầm album."}, "origin_i18n": {"de": "Eine Fandom-Abkürzung des englischen 'Photo Card', etabliert zusammen mit der K-Pop-Industriepraxis, Alben zufällige Karten beizulegen.", "en": "A fandom shortening of the English 'photo card,' settled alongside the K-pop industry practice of bundling random cards with albums.", "es": "Una abreviación de fandom del inglés 'photo card,' asentada junto con la práctica de la industria K-pop de incluir tarjetas aleatorias con álbumes.", "ja": "英語「photo card」を略したファン用語で、アルバムにランダムカードを同封するK-pop業界慣行と共に定着した。", "vi": "Cách viết tắt fandom từ 'photo card' tiếng Anh, định hình cùng thông lệ ngành K-pop kèm thẻ ngẫu nhiên trong album."}, "romanization": "Po-ka", "translations": [{"lang": "🇺🇸 EN", "text": "Photocard"}, {"lang": "🇯🇵 JA", "text": "フォトカード"}, {"lang": "🇨🇳 ZH", "text": "照片卡"}, {"lang": "🇻🇳 VI", "text": "Photocard"}, {"lang": "🇪🇸 ES", "text": "Photocard"}, {"lang": "🇩🇪 DE", "text": "Fotokarte"}], "pronunciation": "[포카]", "related_words": ["굿즈", "홈마"], "short_desc_i18n": {"de": "Eine sammelbare Idol-Fotokarte, oft im Album enthalten", "en": "A collectible idol photo card, often included with albums", "es": "Una tarjeta fotográfica coleccionable de un ídolo, incluida con álbumes", "ja": "アイドルアルバムに入っているコレクション用フォトカード", "vi": "Thẻ ảnh sưu tầm của thần tượng, thường kèm trong album"}}$json$::jsonb);

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "233", "word": "예판", "likes": 0, "saves": 0, "usage": "앨범 구매 계획이나 특전 정보를 이야기할 때 널리 쓴다.", "origin": "'예약'과 '판매'를 합친 일반 용어가 K-pop 앨범 유통 구조에서 초동(발매 첫 주 판매량) 집계를 극대화하는 관행과 맞물려 팬덤 용어로 자리잡았다.", "category": "kpop", "meanings": [{"type": "팬덤 용어", "examples": [{"de": "Ich hab gehört, der Vorbestellungs-Bonus ist eine Fotokarte.", "es": "Dicen que el bono de pre-orden es una fotocard.", "ja": "予約特典でポカくれるらしいよ。", "vi": "Nghe nói quà đặt trước là photocard đấy.", "eng": "I heard the pre-order bonus is a photocard.", "kor": "예판 특전으로 포카 준다던데."}], "definition": "'예약판매'의 줄임말로, 아이돌 앨범이 정식 발매되기 3~4주 전부터 미리 주문받아 파는 것을 이른다. 예판 기간 구매자에게는 포토카드 등 특전이 주어지기도 한다.", "definition_i18n": {"de": "Kurz für 'Vorverkauf.' Bezieht sich darauf, dass Idol-Alben 3-4 Wochen vor der offiziellen Veröffentlichung zur Vorbestellung angeboten werden. Käufer in diesem Zeitraum erhalten oft Boni wie Fotokarten.", "en": "Short for 'advance sale.' Refers to idol albums being sold on pre-order 3-4 weeks before official release. Buyers during this window often get bonuses like photocards.", "es": "Abreviatura de 'venta anticipada.' Se refiere a que los álbumes de ídolos se venden en pre-orden 3-4 semanas antes del lanzamiento oficial. Los compradores en este período suelen recibir bonos como fotocards.", "ja": "「予約販売」の略で、アイドルアルバムが正式発売の3〜4週間前から先行予約で売られることを指す。予約期間の購入者にはフォトカードなどの特典が付くこともある。", "vi": "Viết tắt của 'bán trước.' Chỉ việc album thần tượng được bán đặt trước 3-4 tuần trước phát hành chính thức. Người mua trong giai đoạn này thường nhận quà như photocard."}}], "created_at": "2026-09-04T08:30:00+00:00", "short_desc": "'예약판매'의 줄임말, 발매 전 미리 사는 것", "usage_i18n": {"de": "Wird häufig verwendet, wenn über Albumkaufpläne oder Bonusinformationen gesprochen wird.", "en": "Widely used when discussing album purchase plans or bonus information.", "es": "Ampliamente usado al hablar de planes de compra de álbumes o información de bonos.", "ja": "アルバム購入計画や特典情報を話す時に広く使う。", "vi": "Dùng rộng rãi khi bàn về kế hoạch mua album hay thông tin quà tặng."}, "origin_i18n": {"de": "Der allgemeine Begriff, der 'Reservierung' und 'Verkauf' kombiniert, wurde zu einem Fandom-Standard, verbunden mit der K-Pop-Praxis, die Erstwochenverkaufszahlen (Chodong) zu maximieren.", "en": "The general term combining 'reservation' and 'sale' became a fandom staple, tied to the K-pop practice of maximizing first-week sales (chodong) counts.", "es": "El término general que combina 'reserva' y 'venta' se convirtió en un básico del fandom, ligado a la práctica del K-pop de maximizar el conteo de ventas de primera semana (chodong).", "ja": "「予約」と「販売」を合わせた一般用語が、初動（発売初週売上）集計を最大化するK-popアルバム流通の慣行と結びつきファン用語として定着した。", "vi": "Thuật ngữ chung ghép 'đặt trước' và 'bán' trở thành từ quen thuộc trong fandom, gắn với thông lệ K-pop tối đa hóa doanh số tuần đầu (chodong)."}, "romanization": "Ye-pan", "translations": [{"lang": "🇺🇸 EN", "text": "Pre-order"}, {"lang": "🇯🇵 JA", "text": "予約販売"}, {"lang": "🇨🇳 ZH", "text": "预售"}, {"lang": "🇻🇳 VI", "text": "Đặt trước"}, {"lang": "🇪🇸 ES", "text": "Pre-orden"}, {"lang": "🇩🇪 DE", "text": "Vorbestellung"}], "pronunciation": "[예판]", "related_words": ["총공", "포카"], "short_desc_i18n": {"de": "Kurz für 'Vorbestellung' — vor der offiziellen Veröffentlichung kaufen", "en": "Short for 'pre-order' — buying before official release", "es": "Abreviatura de 'pre-orden' — comprar antes del lanzamiento oficial", "ja": "「予約販売」の略、発売前に先に買うこと", "vi": "Viết tắt của 'đặt trước' — mua trước khi phát hành chính thức"}}$json$::jsonb);

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "234", "word": "팬덤", "likes": 0, "saves": 0, "usage": "특정 아이돌·작품을 좋아하는 팬 전체 집단이나 그 문화를 가리킬 때 널리 쓴다.", "origin": "'fanatic'(광신자)의 'fan'과 접미사 '-dom'의 합성어. 한국에서는 1980년대 조용필의 오빠 부대를 원조로 보며, 1990년대 서태지 팬덤을 거쳐 지금의 K-pop 팬덤 문화로 이어졌다.", "category": "kpop", "meanings": [{"type": "팬덤 용어", "examples": [{"de": "Die Fandom dieser Gruppe ist wirklich riesig.", "es": "El fandom de este grupo es enorme.", "ja": "このグループのファンダム本当に大きいね。", "vi": "Fandom nhóm này to thật sự.", "eng": "This group's fandom is huge.", "kor": "이 그룹 팬덤 진짜 크다."}], "definition": "영어 'fan'(광신자를 뜻하는 fanatic에서 옴)과 영토·집단을 뜻하는 접미사 '-dom'을 합친 말로, 같은 대상을 좋아하는 사람들이 이룬 팬 집단·문화 전반을 이른다.", "definition_i18n": {"de": "Kombiniert 'Fan' (von 'Fanatic') mit dem Suffix '-dom' (Territorium/Bereich); bezieht sich auf die Community und Kultur, die von Menschen gebildet wird, die dieselbe Vorliebe teilen.", "en": "Combines 'fan' (from 'fanatic') with the suffix '-dom' (territory/domain); refers to the community and culture formed by people who share a fandom for the same thing.", "es": "Combina 'fan' (de 'fanatic') con el sufijo '-dom' (territorio/dominio); se refiere a la comunidad y cultura formada por personas que comparten afición por lo mismo.", "ja": "英語「fan」（狂信者を意味するfanatic由来）と領域・集団を意味する接尾辞「-dom」を合わせた語で、同じ対象を好きな人々が形成するファン集団・文化全般を指す。", "vi": "Ghép 'fan' (từ 'fanatic') với hậu tố '-dom' (lãnh thổ/vương quốc); chỉ cộng đồng, văn hóa hình thành bởi những người cùng yêu thích một thứ."}}], "created_at": "2026-09-04T08:30:00+00:00", "short_desc": "같은 대상을 좋아하는 팬들의 집단·문화", "usage_i18n": {"de": "Wird häufig verwendet, um sich auf die gesamte Fan-Community oder -Kultur rund um ein bestimmtes Idol oder Werk zu beziehen.", "en": "Widely used to refer to the entire fan community or culture around a particular idol or work.", "es": "Ampliamente usado para referirse a toda la comunidad o cultura de fans en torno a un ídolo u obra particular.", "ja": "特定のアイドル・作品を好きなファン全体の集団やその文化を指す時に広く使う。", "vi": "Dùng rộng rãi để chỉ toàn bộ cộng đồng fan hoặc văn hóa xoay quanh một thần tượng, tác phẩm cụ thể."}, "origin_i18n": {"de": "Eine Zusammensetzung aus 'Fan' (von 'Fanatic') und dem Suffix '-dom.' In Korea geht es auf Cho Yong-pils Fanbasis der 1980er zurück, entwickelte sich über Seo Taijis Fandom in den 1990ern zur heutigen K-Pop-Fankultur.", "en": "A compound of 'fan' (from 'fanatic') and the suffix '-dom.' In Korea, it's traced to Cho Yong-pil's 1980s fan base, developing through Seo Taiji's 1990s fandom into today's K-pop fan culture.", "es": "Un compuesto de 'fan' (de 'fanatic') y el sufijo '-dom.' En Corea, se remonta a la base de fans de Cho Yong-pil en los 80, desarrollándose a través del fandom de Seo Taiji en los 90 hasta la cultura fan K-pop actual.", "ja": "「fanatic」（狂信者）由来の「fan」と接尾辞「-dom」の合成語。韓国では1980年代チョー・ヨンピルのオッパ部隊を原祖とし、1990年代ソテジのファンダムを経て今のK-popファン文化に続いた。", "vi": "Từ ghép của 'fan' (từ 'fanatic') và hậu tố '-dom.' Ở Hàn, bắt nguồn từ đội quân fan của Cho Yong-pil thập niên 80, phát triển qua fandom Seo Taiji thập niên 90 đến văn hóa fan K-pop ngày nay."}, "romanization": "Paen-deom", "translations": [{"lang": "🇺🇸 EN", "text": "Fandom"}, {"lang": "🇯🇵 JA", "text": "ファンダム"}, {"lang": "🇨🇳 ZH", "text": "粉丝群体"}, {"lang": "🇻🇳 VI", "text": "Fandom"}, {"lang": "🇪🇸 ES", "text": "Fandom"}, {"lang": "🇩🇪 DE", "text": "Fandom"}], "pronunciation": "[팬덤]", "related_words": ["덕질", "총공"], "short_desc_i18n": {"de": "Die Subkultur und Community, die von Fans von etwas gebildet wird", "en": "The subculture and community formed by fans of something", "es": "La subcultura y comunidad formada por fans de algo", "ja": "同じ対象を好きなファンによる集団・文化", "vi": "Cộng đồng, văn hóa hình thành bởi fan của thứ gì đó"}}$json$::jsonb);

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "235", "word": "떡밥", "likes": 0, "saves": 0, "usage": "작품 속 복선이나, 커뮤니티에서 사람들이 추측하며 이야기하는 화제를 가리킬 때 쓴다.", "origin": "낚시에서 물고기를 유인하는 미끼 '떡밥'이 디시인사이드·일베 등 온라인 커뮤니티에서 화제·복선을 뜻하는 은어로 확장돼 쓰이게 됐다.", "category": "drama", "meanings": [{"type": "콘텐츠 용어", "examples": [{"de": "Diese Folge hat die Vorausdeutungen genial aufgelöst.", "es": "Este episodio resolvió el presagio de forma increíble.", "ja": "今回のエピソード、伏線回収やばかった。", "vi": "Tập này giải đáp manh mối đỉnh thật sự.", "eng": "This episode paid off the foreshadowing so well.", "kor": "이번 화 떡밥 회수 미쳤다."}], "definition": "낚시 미끼를 뜻하는 '떡밥'이 인터넷 커뮤니티에서 비유적으로 쓰이며, 드라마·웹툰 등에서 나중에 회수될 복선이나, 팬들 사이에 화제가 되는 이야깃거리를 이른다.", "definition_i18n": {"de": "'Tteokbap' bedeutet wörtlich Angelköder; wird online metaphorisch für eine Handlungsvorausdeutung verwendet, die später aufgelöst wird, oder ein Thema, über das Fans diskutieren und spekulieren.", "en": "'Tteokbap' literally means fishing bait; used metaphorically online to mean a plot foreshadowing that gets paid off later, or a topic that fans discuss and speculate about.", "es": "'Tteokbap' significa literalmente cebo de pesca; se usa metafóricamente en línea para un presagio de trama que se resuelve después, o un tema que los fans discuten y especulan.", "ja": "釣り餌を意味する「떡밥」がネットコミュニティで比喩的に使われ、ドラマ・ウェブトゥーンなどで後で回収される伏線や、ファンの間で話題になる話を指す。", "vi": "'Tteokbap' nghĩa đen là mồi câu cá; dùng ẩn dụ trên mạng chỉ điểm gợi ý cốt truyện được giải đáp sau, hoặc chủ đề fan bàn tán, đoán già đoán non."}}], "created_at": "2026-09-04T08:30:00+00:00", "short_desc": "앞으로의 전개를 암시하는 힌트나 화제거리", "usage_i18n": {"de": "Wird verwendet, um sich auf Handlungsvorausdeutungen in einem Werk oder ein Thema zu beziehen, über das eine Community spekuliert und spricht.", "en": "Used to refer to plot foreshadowing in a work, or a topic that a community speculates and talks about.", "es": "Se usa para referirse a presagios de trama en una obra, o un tema sobre el que una comunidad especula y habla.", "ja": "作品の中の伏線や、コミュニティで人々が推測しながら話す話題を指す時に使う。", "vi": "Dùng để chỉ điểm gợi ý cốt truyện trong tác phẩm, hoặc chủ đề cộng đồng đoán già đoán non, bàn tán."}, "origin_i18n": {"de": "'Tteokbap' (Angelköder, um Fische anzulocken) erweiterte sich zu Online-Community-Slang für ein heißes Thema oder eine Handlungsvorbereitung, auf Seiten wie DC Inside.", "en": "'Tteokbap' (fishing bait to lure fish) extended into online-community slang for a hot topic or plot setup, on sites like DC Inside.", "es": "'Tteokbap' (cebo de pesca para atraer peces) se extendió a jerga de comunidades en línea para un tema candente o preparación de trama, en sitios como DC Inside.", "ja": "釣りで魚をおびき寄せる餌「떡밥」が、DCinsideなどのオンラインコミュニティで話題・伏線を意味する隠語として拡張して使われるようになった。", "vi": "'Tteokbap' (mồi câu cá dụ cá) mở rộng thành tiếng lóng cộng đồng mạng chỉ chủ đề nóng hoặc gợi ý cốt truyện, trên các trang như DC Inside."}, "romanization": "Tteok-bap", "translations": [{"lang": "🇺🇸 EN", "text": "Foreshadowing / teaser"}, {"lang": "🇯🇵 JA", "text": "伏線"}, {"lang": "🇨🇳 ZH", "text": "伏笔/爆料"}, {"lang": "🇻🇳 VI", "text": "Gợi ý cốt truyện"}, {"lang": "🇪🇸 ES", "text": "Presagio / pista"}, {"lang": "🇩🇪 DE", "text": "Vorausdeutung"}], "pronunciation": "[떡빱]", "related_words": ["스포", "정주행", "먹금"], "short_desc_i18n": {"de": "Ein Hinweis oder Gesprächsthema über kommende Handlung", "en": "A teaser hint or talking point about upcoming plot", "es": "Una pista o tema sobre la trama futura", "ja": "今後の展開を示唆するヒントや話題", "vi": "Manh mối, chủ đề gợi ý diễn biến sắp tới"}}$json$::jsonb);

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "236", "word": "떡상", "likes": 0, "saves": 0, "usage": "영상·게시물이 갑자기 화제가 되거나 조회수가 급증했을 때 널리 쓴다.", "origin": "'떡'(엉망진창인 상태를 뜻하는 관용 표현)에 '상승'의 '상'을 붙인 주식·가상화폐 은어에서 시작해, 지금은 분야를 가리지 않고 폭발적 상승을 뜻하는 말로 확장됐다.", "category": "reels", "meanings": [{"type": "인터넷 유행어", "examples": [{"de": "Dieses Video ist über Nacht explodiert.", "es": "Ese video explotó en un día.", "ja": "あの動画、一日で떡상した。", "vi": "Video đó tăng vọt trong một ngày.", "eng": "That video blew up overnight.", "kor": "저 영상 하루만에 떡상했어."}], "definition": "주식·가상화폐 시세가 급등하는 것을 뜻하던 은어에서 온 말로, 지금은 영상 조회수, 인지도, 인기 등이 갑자기 폭발적으로 오르는 상황 전반에 쓴다.", "definition_i18n": {"de": "Von Slang für einen plötzlichen Anstieg des Aktien- oder Kryptopreises; wird heute breit für alles verwendet, das explosionsartig ansteigt — Videoaufrufe, Ruhm, Popularität.", "en": "From slang for a stock or crypto price suddenly spiking; now used broadly for anything — video views, fame, popularity — exploding upward.", "es": "De la jerga para un repentino salto en el precio de acciones o criptomonedas; ahora se usa ampliamente para cualquier cosa (vistas de video, fama, popularidad) que explota hacia arriba.", "ja": "株や仮想通貨の相場が急騰することを意味した隠語由来で、今では動画再生数、知名度、人気などが突然爆発的に上がる状況全般に使う。", "vi": "Từ tiếng lóng chỉ giá cổ phiếu, tiền điện tử tăng vọt đột ngột; nay dùng chung cho bất cứ điều gì (lượt xem video, danh tiếng, độ nổi tiếng) bùng nổ đi lên."}}], "created_at": "2026-09-04T08:30:00+00:00", "short_desc": "인기·조회수·시세 등이 폭발적으로 오르는 것", "usage_i18n": {"de": "Wird häufig verwendet, wenn ein Video oder Beitrag plötzlich viral geht oder die Aufrufe in die Höhe schnellen.", "en": "Widely used when a video or post suddenly goes viral or views spike.", "es": "Ampliamente usado cuando un video o publicación se vuelve viral repentinamente o las vistas se disparan.", "ja": "動画・投稿が急に話題になったり再生数が急増した時に広く使う。", "vi": "Dùng rộng rãi khi video, bài đăng đột nhiên gây sốt hoặc lượt xem tăng vọt."}, "origin_i18n": {"de": "Begann als Börsen-/Krypto-Slang, der 'tteok' (eine Redewendung für einen extremen, chaotischen Zustand) mit 'sang' (Anstieg) kombiniert; heute erweitert, um einen explosiven Anstieg in jedem Bereich zu bedeuten.", "en": "Began as stock/crypto slang combining 'tteok' (an idiom for a messed-up, extreme state) with 'sang' (rise); now expanded to mean an explosive rise in any field.", "es": "Comenzó como jerga bursátil/cripto combinando 'tteok' (un modismo para un estado extremo y desastroso) con 'sang' (subida); ahora se expandió para significar un aumento explosivo en cualquier campo.", "ja": "「떡」（めちゃくちゃな状態を意味する慣用表現）に「上昇」の「상」を付けた株・仮想通貨隠語から始まり、今では分野を問わず爆発的上昇を意味する言葉に拡張した。", "vi": "Bắt đầu là tiếng lóng chứng khoán/tiền điện tử ghép 'tteok' (thành ngữ chỉ trạng thái cực đoan, hỗn loạn) với 'sang' (tăng); nay mở rộng nghĩa tăng vọt bùng nổ trong mọi lĩnh vực."}, "romanization": "Tteok-sang", "translations": [{"lang": "🇺🇸 EN", "text": "Blowing up / skyrocketing"}, {"lang": "🇯🇵 JA", "text": "急上昇"}, {"lang": "🇨🇳 ZH", "text": "暴涨/爆红"}, {"lang": "🇻🇳 VI", "text": "Tăng vọt"}, {"lang": "🇪🇸 ES", "text": "Explotar (popularidad)"}, {"lang": "🇩🇪 DE", "text": "Explodieren (Popularität)"}], "pronunciation": "[떡쌍]", "related_words": ["밈", "챌린지", "떡락"], "short_desc_i18n": {"de": "Ein plötzlicher explosiver Anstieg von Popularität, Aufrufen oder Preis", "en": "A sudden explosive rise in popularity, views, or price", "es": "Un aumento explosivo repentino en popularidad, vistas o precio", "ja": "人気・再生数・相場などが爆発的に上がること", "vi": "Sự tăng vọt đột biến về độ nổi tiếng, lượt xem, giá cả"}}$json$::jsonb);

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "237", "word": "혼밥", "likes": 0, "saves": 0, "usage": "혼자 식사하는 상황을 설명하거나, 혼밥 맛집을 추천할 때 널리 쓴다.", "origin": "1인 가구·1인 생활이 늘면서 '혼자'를 뜻하는 접두사가 '혼밥'·'혼술'·'혼영' 등으로 확장돼 쓰이게 된 대표 사례다.", "category": "daily", "meanings": [{"type": "일상 유행어", "examples": [{"de": "Heute wieder allein essen, aber es ist entspannt.", "es": "Como sola otra vez hoy, pero es cómodo.", "ja": "今日も혼밥だけど気楽。", "vi": "Hôm nay lại ăn một mình nhưng thấy thoải mái.", "eng": "Eating alone again today, but it's comfy.", "kor": "오늘도 혼밥이지만 편해."}], "definition": "'혼자'와 '밥'을 합친 말로, 주변 시선을 신경 쓰지 않고 혼자 식사하는 것을 이른다. 1인 가구 증가와 함께 자연스러운 라이프스타일로 자리 잡았다.", "definition_i18n": {"de": "Kombiniert 'allein' und 'Mahlzeit'; bezieht sich darauf, allein zu essen, ohne sich um die Blicke anderer zu sorgen. Wurde zu einem normalisierten Lebensstil, während Einpersonenhaushalte zunahmen.", "en": "Combines 'alone' and 'meal'; refers to eating by oneself without worrying about others' gaze. Became a normalized lifestyle alongside the rise of single-person households.", "es": "Combina 'solo' y 'comida'; se refiere a comer por cuenta propia sin preocuparse por la mirada ajena. Se normalizó como estilo de vida junto con el aumento de hogares unipersonales.", "ja": "「一人」と「ご飯」を合わせた語で、周囲の目を気にせず一人で食事することを指す。一人世帯の増加と共に自然なライフスタイルとして定着した。", "vi": "Ghép 'một mình' và 'cơm'; chỉ việc ăn một mình mà không quan tâm ánh nhìn xung quanh. Trở thành lối sống bình thường cùng sự gia tăng hộ độc thân."}}], "created_at": "2026-09-04T08:30:00+00:00", "short_desc": "다른 사람 시선 신경 안 쓰고 혼자 밥 먹는 것", "usage_i18n": {"de": "Wird häufig verwendet, um allein essen zu beschreiben oder Restaurants zu empfehlen, die gut zum Alleinessen geeignet sind.", "en": "Widely used to describe eating alone, or to recommend restaurants good for solo dining.", "es": "Ampliamente usado para describir comer solo, o recomendar restaurantes buenos para comer en solitario.", "ja": "一人で食事する状況を説明したり、혼밥に良い店を勧める時に広く使う。", "vi": "Dùng rộng rãi để mô tả việc ăn một mình, hoặc gợi ý quán ăn hợp ăn một mình."}, "origin_i18n": {"de": "Ein Paradebeispiel für das Präfix 'hon-' (allein), das sich auf 'Hon-bap', 'Hon-sul' (allein trinken), 'Hon-yeong' (allein ins Kino) usw. ausweitete, während Einpersonenhaushalte zunahmen.", "en": "A flagship example of the 'hon-' (alone) prefix spreading into 'hon-bap,' 'hon-sul' (solo drinking), 'hon-yeong' (solo movie), etc., as single-person households grew.", "es": "Un ejemplo destacado del prefijo 'hon-' (solo) extendiéndose a 'hon-bap,' 'hon-sul' (beber solo), 'hon-yeong' (ver película solo), etc., a medida que crecían los hogares unipersonales.", "ja": "一人世帯・一人生活の増加に伴い「一人」を意味する接頭辞が「혼밥」「혼술」「혼영」などに拡張して使われるようになった代表例。", "vi": "Ví dụ tiêu biểu của tiền tố 'hon-' (một mình) lan sang 'hon-bap', 'hon-sul' (uống một mình), 'hon-yeong' (xem phim một mình), v.v. khi hộ độc thân tăng."}, "romanization": "Hon-bap", "translations": [{"lang": "🇺🇸 EN", "text": "Eating alone"}, {"lang": "🇯🇵 JA", "text": "一人ご飯"}, {"lang": "🇨🇳 ZH", "text": "一个人吃饭"}, {"lang": "🇻🇳 VI", "text": "Ăn một mình"}, {"lang": "🇪🇸 ES", "text": "Comer solo"}, {"lang": "🇩🇪 DE", "text": "Allein essen"}], "pronunciation": "[혼밥]", "related_words": ["아싸", "혼술"], "short_desc_i18n": {"de": "Allein essen, ohne sich um die Meinung anderer zu sorgen", "en": "Eating alone without worrying about others' opinions", "es": "Comer solo sin preocuparse por la opinión de otros", "ja": "人の目を気にせず一人でご飯を食べること", "vi": "Ăn một mình mà không quan tâm ánh nhìn người khác"}}$json$::jsonb);

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "238", "word": "찐친", "likes": 0, "saves": 0, "usage": "가장 믿고 의지하는 친한 친구를 소개하거나 표현할 때 쓴다.", "origin": "'진짜'를 줄인 접두사 '찐'이 여러 단어에 붙어 진정성을 강조하는 신조어 패턴 중 하나로, '친구'와 결합해 만들어졌다.", "category": "daily", "meanings": [{"type": "일상 유행어", "examples": [{"de": "Sie ist meine echte, treue Freundin.", "es": "Ella es mi amiga de verdad.", "ja": "あの子は私の찐친だよ。", "vi": "Nó là bạn thân thật sự của tôi.", "eng": "She's my real, ride-or-die friend.", "kor": "걔는 내 찐친이야."}], "definition": "'찐'(진짜)과 '친'(친구)을 합친 말로, 겉치레 없이 진심으로 가깝고 믿을 수 있는 친구를 이른다.", "definition_i18n": {"de": "Kombiniert 'jjin' (echt, aufrichtig) mit 'chin' (Freund); bezieht sich auf einen Freund, der wirklich eng und vertrauenswürdig ist, ohne jede Vorgabe.", "en": "Combines 'jjin' (real, genuine) with 'chin' (friend); refers to a friend who is truly close and trustworthy, without any pretense.", "es": "Combina 'jjin' (real, genuino) con 'chin' (amigo); se refiere a un amigo verdaderamente cercano y confiable, sin ninguna pretensión.", "ja": "「찐」（本物）と「친」（友達）を合わせた語で、見栄なく本当に近しく信頼できる友人を指す。", "vi": "Ghép 'jjin' (thật, chân thật) với 'chin' (bạn); chỉ người bạn thực sự thân thiết, đáng tin cậy, không giả tạo."}}], "created_at": "2026-09-04T08:30:00+00:00", "short_desc": "'진짜 친구'의 줄임말, 진심으로 가까운 친구", "usage_i18n": {"de": "Wird verwendet, um den vertrautesten, engsten Freund vorzustellen oder zu beschreiben.", "en": "Used to introduce or describe one's most trusted, closest friend.", "es": "Se usa para presentar o describir al amigo más confiable y cercano.", "ja": "最も信頼し頼れる親友を紹介したり表現したりする時に使う。", "vi": "Dùng để giới thiệu hoặc mô tả người bạn đáng tin cậy, thân thiết nhất."}, "origin_i18n": {"de": "Das Präfix 'jjin' (kurz für 'echt') wird an viele Wörter angehängt in einem Neologismus-Muster, das Authentizität betont; hier kombiniert mit 'Freund.'", "en": "The prefix 'jjin' (short for 'real') attaches to many words in a neologism pattern emphasizing authenticity; combined here with 'friend.'", "es": "El prefijo 'jjin' (abreviatura de 'real') se adjunta a muchas palabras en un patrón de neologismo que enfatiza la autenticidad; combinado aquí con 'amigo.'", "ja": "「本物」を略した接頭辞「찐」が様々な語に付いて真正性を強調する新造語パターンの一つで、「友達」と組み合わさってできた。", "vi": "Tiền tố 'jjin' (viết tắt của 'thật') gắn vào nhiều từ theo mô típ từ mới nhấn mạnh sự chân thật; kết hợp ở đây với 'bạn.'"}, "romanization": "Jjin-chin", "translations": [{"lang": "🇺🇸 EN", "text": "Ride-or-die friend"}, {"lang": "🇯🇵 JA", "text": "本当の親友"}, {"lang": "🇨🇳 ZH", "text": "真朋友"}, {"lang": "🇻🇳 VI", "text": "Bạn thân thật sự"}, {"lang": "🇪🇸 ES", "text": "Amigo verdadero"}, {"lang": "🇩🇪 DE", "text": "Wahrer Freund"}], "pronunciation": "[찐친]", "related_words": ["찐", "절친"], "short_desc_i18n": {"de": "Kurz für 'echter Freund' — ein wirklich enger, aufrichtiger Freund", "en": "Short for 'real friend' — a truly close, genuine friend", "es": "Abreviatura de 'amigo real' — un amigo verdaderamente cercano", "ja": "「本当の友達」の略、心から近しい友人", "vi": "Viết tắt của 'bạn thật' — người bạn thân thiết chân thành"}}$json$::jsonb);



insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "241", "word": "핵이득", "likes": 0, "saves": 0, "usage": "예상 밖의 좋은 일이 생겼을 때 감탄하듯 쓴다.", "origin": "'핵'을 강조 접두사로 쓰는 '핵인싸' 등과 같은 조어 패턴으로, 기존 '개이득'에 더 센 접두사를 붙여 만들어졌다.", "category": "daily", "meanings": [{"type": "인터넷 유행어", "examples": [{"de": "Die U-Bahn kam heute sofort, voller Gewinn.", "es": "Hoy el metro llegó enseguida, qué ganga.", "ja": "今日地下鉄すぐ来た、核이득。", "vi": "Hôm nay tàu điện đến liền, lời to.", "eng": "The subway came right away today, massive win.", "kor": "오늘 지하철 바로 왔다, 핵이득."}], "definition": "'핵'(강조 접두사, '매우'·'엄청'의 뜻)과 '이득'(이익)을 합친 말로, 예상보다 훨씬 좋은 결과나 뜻밖의 횡재를 이른다. '개이득'보다 강조 강도가 더 세다는 인식으로 쓰인다.", "definition_i18n": {"de": "Kombiniert das verstärkende Präfix 'haek' ('sehr'/'super') mit 'ideuk' (Gewinn); bezieht sich auf ein viel besseres Ergebnis als erwartet oder einen unerwarteten Glücksfall. Wird als noch nachdrücklicher als 'gae-ideuk' wahrgenommen.", "en": "Combines the intensifying prefix 'haek' ('very'/'super') with 'ideuk' (gain); refers to a much better-than-expected outcome or unexpected windfall. Perceived as even more emphatic than 'gae-ideuk.'", "es": "Combina el prefijo intensificador 'haek' ('muy'/'súper') con 'ideuk' (ganancia); se refiere a un resultado mucho mejor de lo esperado o una ganancia inesperada. Se percibe como aún más enfático que 'gae-ideuk.'", "ja": "強調接頭辞「핵」（「とても」「めちゃくちゃ」の意）と「이득」（利益）を合わせた語で、予想よりずっと良い結果や思いがけない儲けを指す。「개이득」よりさらに強調が強いと認識されている。", "vi": "Ghép tiền tố nhấn mạnh 'haek' ('rất'/'siêu') với 'ideuk' (lợi); chỉ kết quả tốt hơn mong đợi nhiều hoặc món lợi bất ngờ. Được coi là nhấn mạnh hơn cả 'gae-ideuk.'"}}], "created_at": "2026-09-04T08:30:00+00:00", "short_desc": "'핵'(매우)으로 강조한 엄청난 이득", "usage_i18n": {"de": "Wird als Ausruf verwendet, wenn etwas unerwartet Gutes passiert.", "en": "Used as an exclamation when something unexpectedly good happens.", "es": "Se usa como exclamación cuando ocurre algo inesperadamente bueno.", "ja": "予想外の良いことが起きた時に感嘆するように使う。", "vi": "Dùng như thán từ khi có điều tốt bất ngờ xảy ra."}, "origin_i18n": {"de": "Gebildet auf dieselbe Weise wie 'Haek-inssa' (unter Verwendung von 'haek' als verstärkendes Präfix), indem es an das bestehende 'gae-ideuk' angehängt wird.", "en": "Formed the same way as 'haek-inssa' (using 'haek' as an intensifying prefix), by attaching it to the existing 'gae-ideuk.'", "es": "Formado de la misma manera que 'haek-inssa' (usando 'haek' como prefijo intensificador), añadiéndolo al ya existente 'gae-ideuk.'", "ja": "「핵」を強調接頭辞として使う「핵인싸」などと同じ造語パターンで、既存の「개이득」により強い接頭辞を付けて作られた。", "vi": "Hình thành cùng cách với 'haek-inssa' (dùng 'haek' làm tiền tố nhấn mạnh), gắn vào từ 'gae-ideuk' đã có sẵn."}, "romanization": "Haek-i-deuk", "translations": [{"lang": "🇺🇸 EN", "text": "Massive win / jackpot"}, {"lang": "🇯🇵 JA", "text": "超ラッキー"}, {"lang": "🇨🇳 ZH", "text": "赚翻了"}, {"lang": "🇻🇳 VI", "text": "Lời to"}, {"lang": "🇪🇸 ES", "text": "Ganga enorme"}, {"lang": "🇩🇪 DE", "text": "Riesengewinn"}], "pronunciation": "[핵이득]", "related_words": ["개이득", "핵인싸"], "short_desc_i18n": {"de": "'Riesengewinn' — 'haek' (super) verstärkt 'Gewinn'", "en": "'Massive win' — 'haek' (super) intensifying 'gain'", "es": "'Gran ganancia' — 'haek' (súper) intensifica 'ganancia'", "ja": "「核」（とても）で強調したすごい利益", "vi": "'Lời to' — 'haek' (siêu) nhấn mạnh 'lợi'"}}$json$::jsonb);

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "242", "word": "본캐", "likes": 0, "saves": 0, "usage": "부캐와 구분해 원래 자기 이름·정체성으로 활동하는 것을 가리킬 때 쓴다.", "origin": "온라인 게임에서 여러 캐릭터 중 메인으로 키우는 '본 캐릭터'를 뜻하던 말이 '부캐' 유행과 짝을 이루며 일상 정체성을 가리키는 신조어로 확장됐다.", "category": "work", "meanings": [{"type": "인터넷 유행어", "examples": [{"de": "Das hab ich mit meinem Hauptcharakter gepostet, nicht dem Alter Ego.", "es": "Esto lo publiqué como mi yo principal, no el alter ego.", "ja": "これは부캐じゃなくて本캐で上げた投稿だよ。", "vi": "Cái này mình đăng bằng nhân vật chính, không phải nhân vật phụ đâu.", "eng": "I posted this as my main persona, not the alter-ego.", "kor": "이건 부캐 말고 본캐로 올린 글이야."}], "definition": "게임 용어 '본 캐릭터'(메인으로 키우는 캐릭터)의 줄임말로, 새로운 이름·컨셉 없이 원래 자기 모습·정체성으로 활동하는 것을 이른다. '부캐'의 반대말.", "definition_i18n": {"de": "Kurz für den Gaming-Begriff 'Hauptcharakter' (der primäre Charakter einer Person); bezieht sich darauf, unter dem ursprünglichen Namen/der ursprünglichen Identität aufzutreten, ohne eine neue Persona oder ein Konzept. Das Gegenteil von 부캐.", "en": "Short for the gaming term 'main character' (one's primary character); refers to acting under one's original name/identity, without a new persona or concept. The opposite of 부캐.", "es": "Abreviatura del término de videojuegos 'personaje principal' (el personaje primario de uno); se refiere a actuar bajo el nombre/identidad original de uno, sin una nueva persona o concepto. Lo opuesto a 부캐.", "ja": "ゲーム用語「本キャラクター」（メインで育てるキャラ）の略で、新しい名前やコンセプトなしに元々の自分の姿・アイデンティティで活動することを指す。「부캐」の反対語。", "vi": "Viết tắt của thuật ngữ game 'nhân vật chính' (nhân vật chủ đạo); chỉ việc hoạt động dưới tên, danh tính gốc, không có nhân vật hay khái niệm mới. Trái nghĩa với 부캐."}}], "created_at": "2026-09-04T08:30:00+00:00", "short_desc": "원래 모습으로 활동하는 정체성, 부캐의 반대말", "usage_i18n": {"de": "Wird verwendet, um das Auftreten unter dem ursprünglichen Namen/der Identität von einer 부캐-Persona zu unterscheiden.", "en": "Used to distinguish acting under one's original name/identity from a 부캐 persona.", "es": "Se usa para distinguir actuar bajo el nombre/identidad original de uno de una persona 부캐.", "ja": "부캐と区別して元々の自分の名前・アイデンティティで活動することを指す時に使う。", "vi": "Dùng để phân biệt hoạt động bằng tên, danh tính gốc với nhân vật phụ (부캐)."}, "origin_i18n": {"de": "Ursprünglich ein Online-Gaming-Begriff für den Hauptcharakter unter mehreren gespielten; erweiterte sich zu Alltags-Slang für die Kernidentität einer Person, gepaart mit dem 'Bu-kae'-Trend.", "en": "Originally an online-gaming term for the main character among several one plays; expanded into everyday slang for one's core identity, paired with the 'bu-kae' trend.", "es": "Originalmente un término de videojuegos en línea para el personaje principal entre varios que uno juega; se expandió a jerga cotidiana para la identidad central de uno, emparejado con la tendencia 'bu-kae.'", "ja": "オンラインゲームで複数キャラのうちメインで育てる「本キャラクター」を意味した語が、「부캐」の流行とペアになり日常のアイデンティティを指す新造語に拡張した。", "vi": "Vốn là thuật ngữ game trực tuyến chỉ nhân vật chính trong số nhiều nhân vật chơi; mở rộng thành tiếng lóng đời thường chỉ danh tính cốt lõi, đi cặp với trào lưu 'bu-kae.'"}, "romanization": "Bon-kae", "translations": [{"lang": "🇺🇸 EN", "text": "Main persona"}, {"lang": "🇯🇵 JA", "text": "本キャラ"}, {"lang": "🇨🇳 ZH", "text": "本体角色"}, {"lang": "🇻🇳 VI", "text": "Nhân vật chính"}, {"lang": "🇪🇸 ES", "text": "Yo principal"}, {"lang": "🇩🇪 DE", "text": "Hauptcharakter"}], "pronunciation": "[본캐]", "related_words": ["부캐"], "short_desc_i18n": {"de": "Die ursprüngliche Identität einer Person, das Gegenteil des Alter-Egos", "en": "One's original identity, opposite of the 'alter-ego' persona", "es": "La identidad original de uno, opuesta al alter ego", "ja": "本来の姿で活動するアイデンティティ、부캐の反対語", "vi": "Danh tính gốc, trái nghĩa với nhân vật phụ"}}$json$::jsonb);

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "243", "word": "케바케", "likes": 0, "saves": 0, "usage": "명확한 규칙 없이 상황마다 다르게 판단해야 할 때 쓴다.", "origin": "영어 표현 'case by case'가 한국어 발음으로 줄여져, 직장인·인터넷 커뮤니티에서 상황마다 다르다는 뜻의 관용구로 자리잡았다.", "category": "work", "meanings": [{"type": "직장인·인터넷 유행어", "examples": [{"de": "Das ist von Fall zu Fall, ich kann nichts Genaues sagen.", "es": "Esto es caso por caso, no puedo decir nada seguro.", "ja": "これはケースバイケースだから何とも言えない。", "vi": "Cái này tùy trường hợp, không nói chắc được.", "eng": "It's case by case, I can't really say.", "kor": "이건 케바케라 뭐라 말 못해."}], "definition": "영어 'case by case'를 한국어 발음대로 줄인 말로, 어떤 기준이 상황·경우마다 다르게 적용된다는 뜻이다. '사바사'와 같은 조어 패턴이다.", "definition_i18n": {"de": "Eine koreanische phonetische Verkürzung von 'Case by Case'; bedeutet, dass ein bestimmter Maßstab je nach Situation unterschiedlich gilt. Gebildet auf dieselbe Weise wie 'Sa-ba-sa.'", "en": "A Korean phonetic shortening of 'case by case'; means a given standard applies differently depending on the situation. Formed the same way as 'sa-ba-sa.'", "es": "Una abreviación fonética coreana de 'case by case'; significa que cierto estándar aplica diferente según la situación. Formado igual que 'sa-ba-sa.'", "ja": "英語「case by case」を韓国語発音で略した語で、ある基準が状況・場合ごとに異なって当てはまるという意味。「사바사」と同じ造語パターン。", "vi": "Cách rút gọn phiên âm tiếng Hàn của 'case by case'; nghĩa là một tiêu chuẩn áp dụng khác nhau tùy tình huống. Hình thành cùng cách với 'sa-ba-sa.'"}}], "created_at": "2026-09-04T08:30:00+00:00", "short_desc": "경우에 따라 다르다는 뜻의 줄임말", "usage_i18n": {"de": "Wird verwendet, wenn etwas ohne klare Regel von Fall zu Fall unterschiedlich beurteilt werden muss.", "en": "Used when something needs to be judged differently case by case, without a clear-cut rule.", "es": "Se usa cuando algo debe juzgarse de forma diferente caso por caso, sin una regla clara.", "ja": "明確なルールなく状況ごとに違って判断すべき時に使う。", "vi": "Dùng khi cần đánh giá khác nhau tùy trường hợp, không có quy tắc rõ ràng."}, "origin_i18n": {"de": "Die englische Phrase 'Case by Case' wurde im Koreanischen phonetisch verkürzt und etablierte sich als Redewendung in Arbeitsplatz- und Online-Communities mit der Bedeutung, dass es je nach Situation variiert.", "en": "The English phrase 'case by case' was shortened phonetically in Korean, settling as an idiom in workplace and online communities meaning it varies by situation.", "es": "La frase inglesa 'case by case' se abrevió fonéticamente en coreano, asentándose como modismo en comunidades laborales y en línea que significa que varía según la situación.", "ja": "英語表現「case by case」が韓国語発音で略され、会社員・ネットコミュニティで状況ごとに違うという意味の慣用句として定着した。", "vi": "Cụm từ tiếng Anh 'case by case' được rút gọn phiên âm tiếng Hàn, định hình thành thành ngữ trong cộng đồng công sở, mạng nghĩa là tùy tình huống."}, "romanization": "Ke-ba-ke", "translations": [{"lang": "🇺🇸 EN", "text": "Case by case"}, {"lang": "🇯🇵 JA", "text": "ケースバイケース"}, {"lang": "🇨🇳 ZH", "text": "具体情况具体分析"}, {"lang": "🇻🇳 VI", "text": "Tùy trường hợp"}, {"lang": "🇪🇸 ES", "text": "Caso por caso"}, {"lang": "🇩🇪 DE", "text": "Von Fall zu Fall"}], "pronunciation": "[케바케]", "related_words": ["사바사"], "short_desc_i18n": {"de": "'Fall zu Fall' — es kommt auf die jeweilige Situation an", "en": "'Case by case' — it depends on the specific situation", "es": "'Caso por caso' — depende de la situación específica", "ja": "場合によって違うという意味の略語", "vi": "'Tùy trường hợp' — tùy vào tình huống cụ thể"}}$json$::jsonb);

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "244", "word": "월급 루팡", "likes": 0, "saves": 0, "usage": "업무 태만한 동료를 가볍게 놀리거나, 스스로를 자조적으로 표현할 때 쓴다.", "origin": "'월급 도둑'이라는 기존 표현이, 프랑스 소설 속 괴도 '아르센 뤼팽'의 이름과 결합해 '월급 루팡'으로 변형됐다. 2011년 무렵부터 널리 쓰이기 시작했다는 것이 정설이다.", "category": "work", "meanings": [{"type": "직장인 유행어", "examples": [{"de": "Der ist ein totaler Gehaltsdieb.", "es": "Él es un total ladrón de sueldo.", "ja": "あいつ完全に월급 루팡じゃん。", "vi": "Nó đúng kiểu lãnh lương mà không làm gì luôn.", "eng": "He's a total salary Lupin.", "kor": "쟤 완전 월급 루팡이잖아."}], "definition": "'월급'과 괴도 캐릭터 '아르센 뤼팽'을 합친 말로, 맡은 업무를 제대로 안 하면서도 월급은 꼬박꼬박 받아가는 직장인을 이른다. 줄여서 '월루'라고도 한다.", "definition_i18n": {"de": "Kombiniert 'wolgeup' (Gehalt) mit der Gentleman-Dieb-Figur 'Arsène Lupin'; bezieht sich auf einen Angestellten, der seine Arbeit nicht richtig macht, aber trotzdem regelmäßig sein Gehalt bezieht. Oft zu 'Wollu' verkürzt.", "en": "Combines 'wolgeup' (salary) with the gentleman-thief character 'Arsène Lupin'; refers to an employee who doesn't properly do their job yet still draws a regular paycheck. Often shortened to 'wollu.'", "es": "Combina 'wolgeup' (salario) con el personaje ladrón caballero 'Arsène Lupin'; se refiere a un empleado que no hace bien su trabajo pero sigue cobrando un sueldo regular. A menudo abreviado 'wollu.'", "ja": "「給料」と怪盗キャラクター「アルセーヌ・ルパン」を合わせた語で、担当業務をきちんとやらないのに給料だけはしっかりもらう会社員を指す。略して「월루」とも言う。", "vi": "Ghép 'wolgeup' (lương) với nhân vật đại đạo 'Arsène Lupin'; chỉ nhân viên không làm tốt việc được giao nhưng vẫn nhận lương đều đặn. Thường rút gọn thành 'wollu.'"}}], "created_at": "2026-09-04T08:30:00+00:00", "short_desc": "일은 안 하면서 월급만 받아가는 사람", "usage_i18n": {"de": "Wird verwendet, um einen faulenzenden Kollegen leicht zu necken, oder selbstironisch über sich selbst.", "en": "Used to lightly tease a slacking coworker, or self-deprecatingly about oneself.", "es": "Se usa para burlarse ligeramente de un compañero holgazán, o de forma autocrítica sobre uno mismo.", "ja": "仕事をサボる同僚を軽くからかったり、自分自身を自嘲的に表現する時に使う。", "vi": "Dùng để trêu nhẹ đồng nghiệp lười biếng, hoặc tự trào về bản thân."}, "origin_i18n": {"de": "Die bestehende Phrase 'wolgeup dodeuk' (Gehaltsdieb) wandelte sich zu 'wolgeup rupang', indem sie mit Arsène Lupin, dem Gentleman-Dieb aus französischen Romanen, kombiniert wurde. Es wird allgemein angenommen, dass sie sich seit etwa 2011 verbreitete.", "en": "The existing phrase 'wolgeup dodeuk' (salary thief) morphed into 'wolgeup rupang' by combining it with Arsène Lupin, the gentleman thief from French novels. Widely believed to have spread from around 2011.", "es": "La frase existente 'wolgeup dodeuk' (ladrón de sueldo) se transformó en 'wolgeup rupang' al combinarla con Arsène Lupin, el ladrón caballero de novelas francesas. Se cree ampliamente que se difundió desde alrededor de 2011.", "ja": "既存の表現「給料泥棒」が、フランス小説の怪盗「アルセーヌ・ルパン」の名前と結びつき「월급 루팡」に変化した。2011年頃から広く使われ始めたというのが定説。", "vi": "Cụm từ có sẵn 'wolgeup dodeuk' (kẻ trộm lương) biến thành 'wolgeup rupang' khi kết hợp với Arsène Lupin, tên trộm quý tộc trong tiểu thuyết Pháp. Được cho là lan rộng từ khoảng năm 2011."}, "romanization": "Wol-geup Ru-pang", "translations": [{"lang": "🇺🇸 EN", "text": "Salary Lupin (slacker)"}, {"lang": "🇯🇵 JA", "text": "給料泥棒"}, {"lang": "🇨🇳 ZH", "text": "薪水小偷"}, {"lang": "🇻🇳 VI", "text": "Trộm lương (lười)"}, {"lang": "🇪🇸 ES", "text": "Ladrón de sueldo"}, {"lang": "🇩🇪 DE", "text": "Gehaltsdieb"}], "pronunciation": "[월급 루팡]", "related_words": ["칼퇴", "프리랜서"], "short_desc_i18n": {"de": "Ein Angestellter, der kaum arbeitet, aber trotzdem sein Gehalt kassiert", "en": "An employee who does minimal work but still collects a paycheck", "es": "Un empleado que apenas trabaja pero sigue cobrando el sueldo", "ja": "仕事はろくにせず給料だけもらう人", "vi": "Nhân viên làm ít nhưng vẫn nhận lương đều"}}$json$::jsonb);

-- 아래 2개는 후보 테이블에 없던 신규 작성분 (운영자 지시: 떡상·떡밥과 짝으로 함께 등록).
-- 함께 지시된 '개이득'은 이미 id 11로 사전에 있어 새로 만들지 않았다.


insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "246", "word": "떡락", "likes": 0, "saves": 0, "usage": "주가·조회수·인기가 급락했을 때 쓴다. 떡상과 짝을 이뤄 함께 쓰이는 경우가 많다.", "origin": "'떡상'과 같은 조어 방식으로, '상승'의 '상' 자리에 '하락'의 '락'을 넣어 만든 반대말. 주식·가상화폐 커뮤니티에서 시작해 인기·조회수 전반으로 확장됐다.", "category": "reels", "meanings": [{"type": "인터넷 유행어", "examples": [{"de": "Die Aktie ist über Nacht abgestürzt.", "es": "La acción se desplomó de la noche a la mañana.", "ja": "株が一晩で떡락した。", "vi": "Cổ phiếu rớt thẳng đứng sau một đêm.", "eng": "The stock tanked overnight.", "kor": "주식 하루만에 떡락했어."}], "definition": "'떡상'의 반대말로, 시세·조회수·인기 등이 갑자기 폭락하는 것을 이른다. 심각한 손실보다는 자조 섞인 말투로 쓰는 경우가 많다.", "definition_i18n": {"de": "Das Gegenteil von 'tteoksang'; bezeichnet einen plötzlichen Absturz von Preis, Aufrufen oder Popularität. Meist mit selbstironischem Unterton statt als ernste Verlustmeldung.", "en": "The opposite of 'tteoksang'; means a price, view count, or popularity suddenly crashing. Usually said with a self-mocking tone rather than as a serious report of loss.", "es": "Lo opuesto a 'tteoksang'; significa que un precio, número de vistas o popularidad se desploma de golpe. Suele decirse con tono de autoburla más que como un informe serio de pérdidas.", "ja": "「떡상」の反対語で、相場・再生数・人気などが急落することを指す。深刻な損失というより自嘲混じりの口調で使うことが多い。", "vi": "Trái nghĩa với 'tteoksang'; chỉ giá, lượt xem hay độ nổi tiếng rớt đột ngột. Thường nói với giọng tự giễu hơn là báo cáo thua lỗ nghiêm túc."}}], "created_at": "2026-09-04T08:30:00+00:00", "short_desc": "인기·조회수·시세 등이 폭락하는 것", "usage_i18n": {"de": "Wird verwendet, wenn Kurs, Aufrufe oder Popularität einbrechen; tritt oft im Paar mit 'tteoksang' auf.", "en": "Used when a price, views, or popularity crashes; often appears paired with 'tteoksang.'", "es": "Se usa cuando un precio, las vistas o la popularidad se hunden; suele aparecer emparejado con 'tteoksang.'", "ja": "株価・再生数・人気が急落した時に使う。「떡상」と対にして一緒に使われることが多い。", "vi": "Dùng khi giá, lượt xem, độ nổi tiếng lao dốc; thường đi cặp với 'tteoksang.'"}, "origin_i18n": {"de": "Nach demselben Muster wie 'tteoksang' gebildet, indem 'sang' (Anstieg) durch 'rak' (Fall) ersetzt wurde. Begann in Aktien- und Krypto-Communities und weitete sich auf Popularität und Aufrufe allgemein aus.", "en": "Formed on the same pattern as 'tteoksang,' swapping 'sang' (rise) for 'rak' (fall). It began in stock and crypto communities and spread to popularity and view counts generally.", "es": "Formado con el mismo patrón que 'tteoksang,' cambiando 'sang' (subida) por 'rak' (caída). Comenzó en comunidades bursátiles y cripto y se extendió a la popularidad y las vistas en general.", "ja": "「떡상」と同じ造語方式で、「上昇」の「상」の位置に「下落」の「락」を入れて作った反対語。株・仮想通貨コミュニティで始まり、人気・再生数全般に拡張した。", "vi": "Tạo theo cùng mô típ với 'tteoksang', thay 'sang' (tăng) bằng 'rak' (giảm). Bắt đầu từ cộng đồng chứng khoán, tiền điện tử rồi lan sang độ nổi tiếng, lượt xem nói chung."}, "romanization": "Tteok-rak", "translations": [{"lang": "🇺🇸 EN", "text": "Tanking / crashing"}, {"lang": "🇯🇵 JA", "text": "暴落"}, {"lang": "🇨🇳 ZH", "text": "暴跌"}, {"lang": "🇻🇳 VI", "text": "Rớt thảm"}, {"lang": "🇪🇸 ES", "text": "Desplomarse"}, {"lang": "🇩🇪 DE", "text": "Absturz"}], "pronunciation": "[떵낙]", "related_words": ["떡상", "존버"], "short_desc_i18n": {"de": "Ein plötzlicher Absturz von Popularität, Aufrufen oder Preis", "en": "A sudden crash in popularity, views, or price", "es": "Un desplome repentino en popularidad, vistas o precio", "ja": "人気・再生数・相場などが暴落すること", "vi": "Sự lao dốc đột ngột về độ nổi tiếng, lượt xem, giá cả"}}$json$::jsonb);

insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "247", "word": "먹금", "likes": 0, "saves": 0, "usage": "댓글창에서 어그로를 끄는 사람에게 반응하지 말자고 할 때 쓴다. 당사자에게 직접 말하기보다 다른 사람들에게 하는 말이다.", "origin": "'먹이 금지'의 줄임말. 관심을 먹이에 빗대, 반응해 주면 더 심해진다는 인터넷 커뮤니티의 오랜 경험칙에서 나왔다. 영어권의 'don't feed the troll'과 같은 발상이다.", "category": "new-slang", "meanings": [{"type": "인터넷 유행어", "examples": [{"de": "Nicht füttern, der will doch nur Aufmerksamkeit.", "es": "No le deis de comer, solo busca atención.", "ja": "餌やり禁止、ただの構ってちゃんだから。", "vi": "Đừng cho ăn, nó chỉ muốn gây chú ý thôi.", "eng": "Don't feed it, they just want attention.", "kor": "먹금하자, 그냥 관심 끌려는 거야."}], "definition": "'먹이 금지'의 줄임말로, 어그로를 끌거나 시비를 거는 사람에게 대꾸하지 말자는 뜻이다. 반응 자체가 상대가 원하는 먹이라는 전제가 깔려 있다.", "definition_i18n": {"de": "Kurz für 'Fütterungsverbot'; bedeutet, jemandem nicht zu antworten, der provoziert oder Streit sucht. Dahinter steht die Annahme, dass die Reaktion selbst das Futter ist, das die Person will.", "en": "Short for 'no feeding'; means not replying to someone who is baiting or picking fights. The premise is that the reaction itself is the food they are after.", "es": "Abreviatura de 'prohibido alimentar'; significa no responder a quien provoca o busca pelea. La premisa es que la reacción misma es el alimento que busca.", "ja": "「餌やり禁止」の略で、煽ったり喧嘩を売る人に反応しないでおこうという意味。反応そのものが相手の欲しがる餌だという前提がある。", "vi": "Viết tắt của 'cấm cho ăn'; nghĩa là đừng đáp lại người đang khiêu khích hay gây sự. Tiền đề là chính phản ứng mới là thứ họ muốn."}}], "created_at": "2026-09-04T08:30:00+00:00", "short_desc": "'먹이 금지' — 어그로에 반응하지 말자는 말", "usage_i18n": {"de": "Wird in Kommentarspalten verwendet, um andere zu bitten, auf einen Provokateur nicht zu reagieren; richtet sich an die Umstehenden, nicht an die Person selbst.", "en": "Used in comment threads to ask others not to react to someone baiting; addressed to the bystanders, not to the person themselves.", "es": "Se usa en los comentarios para pedir a los demás que no reaccionen ante quien provoca; va dirigido a los presentes, no a esa persona.", "ja": "コメント欄で煽っている人に反応しないようにと言う時に使う。本人に直接言うより、周りの人に向けて言う言葉。", "vi": "Dùng trong phần bình luận để nhắc mọi người đừng phản ứng với kẻ khiêu khích; nói với những người xung quanh chứ không phải với chính người đó."}, "origin_i18n": {"de": "Kurzform von 'meogi geumji' (Fütterungsverbot). Sie stammt aus der langjährigen Erfahrungsregel von Online-Communities, dass Aufmerksamkeit wie Futter wirkt und Reagieren alles schlimmer macht — derselbe Gedanke wie das englische 'don't feed the troll.'", "en": "A contraction of 'meogi geumji' (no feeding). It comes from the long-standing online-community rule of thumb that attention works like food and reacting only makes things worse — the same idea as the English 'don't feed the troll.'", "es": "Contracción de 'meogi geumji' (prohibido alimentar). Viene de la vieja regla empírica de las comunidades en línea de que la atención funciona como alimento y reaccionar solo empeora las cosas — la misma idea que el inglés 'don't feed the troll.'", "ja": "「먹이 금지」（餌やり禁止）の略。関心を餌に見立て、反応するとかえって悪化するというネットコミュニティの長年の経験則から生まれた。英語圏の「don't feed the troll」と同じ発想。", "vi": "Rút gọn của 'meogi geumji' (cấm cho ăn). Xuất phát từ kinh nghiệm lâu năm của cộng đồng mạng rằng sự chú ý giống như thức ăn, phản ứng chỉ làm mọi thứ tệ hơn — cùng ý với 'don't feed the troll' trong tiếng Anh."}, "romanization": "Meok-geum", "translations": [{"lang": "🇺🇸 EN", "text": "Don't feed the troll"}, {"lang": "🇯🇵 JA", "text": "餌やり禁止（スルー推奨）"}, {"lang": "🇨🇳 ZH", "text": "别理喷子"}, {"lang": "🇻🇳 VI", "text": "Đừng cho troll ăn"}, {"lang": "🇪🇸 ES", "text": "No alimentes al troll"}, {"lang": "🇩🇪 DE", "text": "Trolle nicht füttern"}], "pronunciation": "[먹끔]", "related_words": ["어그로", "떡밥"], "short_desc_i18n": {"de": "'Nicht füttern' — reagiere nicht auf Provokationen", "en": "'No feeding' — don't react to someone baiting you", "es": "'No alimentar' — no reacciones a quien provoca", "ja": "「餌やり禁止」——煽りに反応しないという意味", "vi": "'Cấm cho ăn' — đừng phản ứng với kẻ khiêu khích"}}$json$::jsonb);

-- 병기 표기: 새 표제어를 만드는 대신 기존 TMI(21)·존맛탱(102)에 별칭과 설명을 붙인다.
update public.words set
  aliases = array['티엠아이'],
  usage = coalesce(usage,'') || ' 알파벳 TMI와 한글 티엠아이 중 무엇으로 검색해도 이 항목 하나가 나온다.',
  usage_i18n = coalesce(usage_i18n,'{}'::jsonb) || jsonb_build_object(
    'en', coalesce(usage_i18n->>'en','') || ' Searching either TMI or 티엠아이 leads to this single entry.',
    'ja', coalesce(usage_i18n->>'ja','') || ' TMI でも 티엠아이 でも検索するとこの一件が出る。',
    'es', coalesce(usage_i18n->>'es','') || ' Buscar TMI o 티엠아이 lleva siempre a esta misma entrada.',
    'vi', coalesce(usage_i18n->>'vi','') || ' Tìm TMI hay 티엠아이 đều ra đúng mục này.',
    'de', coalesce(usage_i18n->>'de','') || ' Ob TMI oder 티엠아이 — die Suche führt immer zu diesem einen Eintrag.')
where id = '21';

update public.words set
  aliases = array['JMT','제이엠티','존맛'],
  usage = coalesce(usage,'') || ' 한글 존맛탱, 알파벳 JMT, 한글 표기 제이엠티 중 무엇으로 검색해도 이 항목 하나가 나온다.',
  usage_i18n = coalesce(usage_i18n,'{}'::jsonb) || jsonb_build_object(
    'en', coalesce(usage_i18n->>'en','') || ' Searching 존맛탱, JMT or 제이엠티 all lead to this single entry.',
    'ja', coalesce(usage_i18n->>'ja','') || ' 존맛탱・JMT・제이엠티 のどれで検索してもこの一件が出る。',
    'es', coalesce(usage_i18n->>'es','') || ' Buscar 존맛탱, JMT o 제이엠티 lleva siempre a esta misma entrada.',
    'vi', coalesce(usage_i18n->>'vi','') || ' Tìm 존맛탱, JMT hay 제이엠티 đều ra đúng mục này.',
    'de', coalesce(usage_i18n->>'de','') || ' Ob 존맛탱, JMT oder 제이엠티 — die Suche führt immer zu diesem einen Eintrag.')
where id = '102';

-- payload에 aliases 키가 없는 단어는 jsonb_populate_record가 NULL을 넣는다. 읽는 쪽은
-- `row.aliases ?? []`로 받지만, 저장값도 빈 배열로 맞춰 둔다.
update public.words set aliases = '{}' where aliases is null;

commit;

